/**
 * Local HTTPS: a per-install certificate authority ("Vela Local CA") and one certificate per site
 * domain, signed with it. Generated by the PHP CLI's openssl extension (PHP ships OpenSSL; Windows
 * has no openssl.exe). The CA is trusted in the *user's* root store via certutil (Windows asks once).
 */
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { dataDir, type Config } from "./config";
import { runPhp } from "./php";
import { exec, sysTool } from "./proc";

const sslDir = (cfg: Config) => dataDir(cfg.root, "ssl");
export const caFiles = (cfg: Config) => ({ crt: join(sslDir(cfg), "vela-ca.crt"), key: join(sslDir(cfg), "vela-ca.key") });

/** Certificate files of a domain, or null when not generated yet. */
export function siteCert(cfg: Config, domain: string): { crt: string; key: string } | null {
  const crt = join(sslDir(cfg), `${domain}.crt`);
  const key = join(sslDir(cfg), `${domain}.key`);
  return existsSync(crt) && existsSync(key) ? { crt, key } : null;
}

const CONF = (alt: string) => `[req]
distinguished_name = dn
[dn]
[v3_ca]
basicConstraints = critical, CA:TRUE, pathlen:0
keyUsage = critical, keyCertSign, cRLSign
subjectKeyIdentifier = hash
[v3_site]
basicConstraints = critical, CA:FALSE
keyUsage = critical, digitalSignature, keyEncipherment
extendedKeyUsage = serverAuth
subjectAltName = ${alt || "DNS:localhost"}
`;

// Paths and names arrive through env vars: nothing user-controlled is spliced into PHP code.
const SCRIPT = `<?php
function fail($m) { while ($e = openssl_error_string()) $m .= "\\n" . $e; fwrite(STDERR, $m); exit(1); }
if (!extension_loaded('openssl')) fail('PHP OpenSSL extension not loaded');
$cnf = getenv('VELA_CNF');
$opt = ['config' => $cnf, 'digest_alg' => 'sha256'];
if (getenv('VELA_MODE') === 'ca') {
  $key = openssl_pkey_new(['private_key_bits' => 2048, 'private_key_type' => OPENSSL_KEYTYPE_RSA, 'config' => $cnf]) ?: fail('CA key');
  $csr = openssl_csr_new(['commonName' => 'Vela Local CA', 'organizationName' => 'Vela'], $key, $opt) ?: fail('CA CSR');
  $crt = openssl_csr_sign($csr, null, $key, 3650, $opt + ['x509_extensions' => 'v3_ca'], random_int(1, PHP_INT_MAX)) ?: fail('CA signature');
} else {
  $caCrt = file_get_contents(getenv('VELA_CA_CRT'));
  $caKey = openssl_pkey_get_private(file_get_contents(getenv('VELA_CA_KEY'))) ?: fail('CA key unreadable');
  $key = openssl_pkey_new(['private_key_bits' => 2048, 'private_key_type' => OPENSSL_KEYTYPE_RSA, 'config' => $cnf]) ?: fail('site key');
  $csr = openssl_csr_new(['commonName' => getenv('VELA_CN')], $key, $opt) ?: fail('site CSR');
  $crt = openssl_csr_sign($csr, $caCrt, $caKey, 825, $opt + ['x509_extensions' => 'v3_site'], random_int(1, PHP_INT_MAX)) ?: fail('site signature');
}
openssl_x509_export_to_file($crt, getenv('VELA_OUT_CRT')) || fail('write certificate');
openssl_pkey_export_to_file($key, getenv('VELA_OUT_KEY'), null, ['config' => $cnf]) || fail('write key');
`;

async function generate(cfg: Config, env: Record<string, string>, alt: string): Promise<void> {
  mkdirSync(sslDir(cfg), { recursive: true });
  const cnf = join(sslDir(cfg), `openssl-${env.VELA_MODE}.cnf`);
  writeFileSync(cnf, CONF(alt), "utf8");
  const r = await runPhp(cfg, [], { stdin: SCRIPT, env: { ...env, VELA_CNF: cnf, OPENSSL_CONF: cnf } });
  if (r.code !== 0) throw new Error(`Certificate: ${(r.stderr || r.stdout).trim().slice(-400) || "PHP failed"}`);
}

/** Create the CA once. */
export async function ensureCa(cfg: Config): Promise<{ crt: string; key: string }> {
  const ca = caFiles(cfg);
  if (!existsSync(ca.crt) || !existsSync(ca.key)) await generate(cfg, { VELA_MODE: "ca", VELA_OUT_CRT: ca.crt, VELA_OUT_KEY: ca.key }, "");
  return ca;
}

/** Certificate for a domain (and its subdomains), signed by the Vela CA. */
export async function ensureSiteCert(cfg: Config, domain: string): Promise<{ crt: string; key: string }> {
  const have = siteCert(cfg, domain);
  if (have) return have;
  const ca = await ensureCa(cfg);
  const crt = join(sslDir(cfg), `${domain}.crt`);
  const key = join(sslDir(cfg), `${domain}.key`);
  await generate(cfg, { VELA_MODE: "site", VELA_CN: domain, VELA_CA_CRT: ca.crt, VELA_CA_KEY: ca.key, VELA_OUT_CRT: crt, VELA_OUT_KEY: key }, `DNS:${domain}, DNS:*.${domain}`);
  return { crt, key };
}

/** Is the Vela CA in the user's trusted roots? */
export async function caTrusted(cfg: Config): Promise<boolean> {
  if (!existsSync(caFiles(cfg).crt)) return false;
  const r = await exec([sysTool("certutil.exe"), "-user", "-verify", caFiles(cfg).crt], { timeoutMs: 15000 });
  return r.code === 0 && !/UNTRUSTED_ROOT|CERT_E_UNTRUSTEDROOT|0x800b0109/i.test(r.stdout);
}

/** Add the CA to the user's trusted roots (Windows shows its own confirmation). */
export async function trustCa(cfg: Config): Promise<void> {
  const ca = await ensureCa(cfg);
  const r = await exec([sysTool("certutil.exe"), "-user", "-addstore", "Root", ca.crt], { timeoutMs: 120000 });
  if (r.code !== 0) throw new Error(/cancel/i.test(r.stdout + r.stderr) ? "Certificate installation canceled" : (r.stdout || r.stderr).trim().slice(-300));
}
